// Cache simples de formatadores, útil em aplicações multilingues
const cache = new Map();
function formatador(locale, opcoes) {
  const chave = locale + JSON.stringify(opcoes);
  if (!cache.has(chave)) {
    cache.set(chave, new Intl.NumberFormat(locale, opcoes));
  }
  return cache.get(chave);
}

console.log(formatador("pt-PT", { style: "currency", currency: "EUR" }).format(10)); // "10,00 €"
console.log(formatador("pt-PT", { style: "currency", currency: "EUR" }).format(20)); // "20,00 €"
console.log(cache.size); // 1

