const euros = new Intl.NumberFormat("pt-PT", { style: "currency", currency: "EUR" });
const dolares = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" });

function formatarPrecos(precos) {
  return precos.map((p) => euros.format(p));
}

const precos = [4.5, 19.99, 1250, 0.75];
console.log(formatarPrecos(precos));
// [ '4,50 €', '19,99 €', '1250,00 €', '0,75 €' ]

const total = precos.reduce((acc, p) => acc + p, 0);
console.log(`Total: ${euros.format(total)}`); // "Total: 1275,24 €"
console.log(dolares.format(total));           // "$1,275.24"

const produtos = ["Óleo", "arroz", "açúcar", "Azeite", "item10", "item2", "ovo"];

function ordenarPT(lista) {
  const colator = new Intl.Collator("pt-PT", { numeric: true, sensitivity: "base" });
  return [...lista].sort(colator.compare);
}

console.log([...produtos].sort());
// [ 'Azeite', 'arroz', 'açúcar', 'item10', 'item2', 'ovo', 'Óleo' ]

console.log(ordenarPT(produtos));
// [ 'açúcar', 'arroz', 'Azeite', 'item2', 'item10', 'Óleo', 'ovo' ]

console.log(produtos[0]); // "Óleo" (o array original ficou intacto)

const DIVISOES = [
  ["second", 60],
  ["minute", 60],
  ["hour", 24],
  ["day", 7],
  ["week", 4.34524],
  ["month", 12],
  ["year", Infinity]
];

const rtf = new Intl.RelativeTimeFormat("pt-PT", { numeric: "auto" });

function tempoRelativo(data, referencia) {
  let delta = (data.getTime() - referencia.getTime()) / 1000;
  for (const [unidade, limite] of DIVISOES) {
    if (Math.abs(delta) < limite) {
      return rtf.format(Math.round(delta), unidade);
    }
    delta /= limite;
  }
  return rtf.format(Math.round(delta), "year");
}

const referencia = new Date("2026-03-15T10:00:00Z");
console.log(tempoRelativo(new Date("2026-03-15T09:59:30Z"), referencia)); // "há 30 segundos"
console.log(tempoRelativo(new Date("2026-03-15T12:00:00Z"), referencia)); // "dentro de 2 horas"
console.log(tempoRelativo(new Date("2026-03-14T10:00:00Z"), referencia)); // "ontem"
console.log(tempoRelativo(new Date("2026-03-01T10:00:00Z"), referencia)); // "há 2 semanas"
console.log(tempoRelativo(new Date("2025-12-15T10:00:00Z"), referencia)); // "há 3 meses"

const LOCALE = "pt-PT";

const moeda = new Intl.NumberFormat(LOCALE, { style: "currency", currency: "EUR" });
const lista = new Intl.ListFormat(LOCALE, { style: "long", type: "conjunction" });
const plural = new Intl.PluralRules(LOCALE);
const dataFmt = new Intl.DateTimeFormat(LOCALE, { dateStyle: "long", timeZone: "Europe/Lisbon" });

const PALAVRAS = { one: "artigo", other: "artigos" };

function descreverEncomenda(itens, entrega) {
  const total = itens.reduce((acc, item) => acc + item.preco * item.quantidade, 0);
  const unidades = itens.reduce((acc, item) => acc + item.quantidade, 0);
  const palavra = PALAVRAS[plural.select(unidades)] ?? PALAVRAS.other;
  const nomes = lista.format(itens.map((item) => item.nome));
  return `${unidades} ${palavra} (${nomes}), num total de ${moeda.format(total)}, com entrega a ${dataFmt.format(entrega)}.`;
}

const entrega = new Date("2026-03-15T10:00:00Z");

const carrinho = [
  { nome: "maçãs", preco: 2.49, quantidade: 2 },
  { nome: "peras", preco: 3.1, quantidade: 1 },
  { nome: "uvas", preco: 4.75, quantidade: 1 }
];

console.log(descreverEncomenda(carrinho, entrega));
// "4 artigos (maçãs, peras e uvas), num total de 12,83 €, com entrega a 15 de março de 2026."

console.log(descreverEncomenda([{ nome: "pão", preco: 1.2, quantidade: 1 }], entrega));
// "1 artigo (pão), num total de 1,20 €, com entrega a 15 de março de 2026."
